// UUSD / UETH / UBNB token icon generator -- v3.1 seal format
//
// Market research conclusion (programmatic stats + visual inspection of 15 samples):
//   flat single-hue ground + white/dark monochrome parent glyph; derivative tokens 100% keep the
//   parent asset glyph, wrapper identity = ground color
//   -> v1 cascading echo / v2 sunset gradient are both retired (multi-hue smears at small sizes,
//   violating the category pattern)
//
// v3.1 format:
//   - Ground: brand yellow #FCEE0A flat-filled circle (logo-yellow; the wordmark body shares the
//     color, icon = brand seal)
//   - Glyph: magenta #FF06B5 (the bright tier is "large type
//     and graphics only", graphics are legal; contrast 2.9:1 -- alternate on the ink/magenta
//     highlight contrast row)
//   - Glyph geometry = redrawn to the current official mark proportions of the anchored asset
//     ($ single vertical stroke / ETH waist-seam diamond / BNB Chain current mark "upper+lower
//     chevrons + hexagonal ring + two slanted arms" -- note: Binance's four diamonds are the
//     exchange logo, not the chain mark)
//   - Proportion balancing: largest glyph ink edge ≈ 62-70% of the diameter across the three coins
//     (uusd 64 / ueth 70 / ubnb 62), ink-area-level balance (36k-45k/512²)
//   - No gradient, no stroke, no corner badge: pure two-color
//
// Usage: pnpm node script/token-icons/build.mjs   (writes into docs/design/token-icons/)

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const OUT = join(ROOT, 'docs', 'design', 'token-icons');

const YELLOW = '#FCEE0A'; // --logo-yellow (ground)
const INK = '#0A0A10'; // site black (ink variant glyph)
const MAGENTA = '#FF06B5'; // --logo-magenta-bright (primary glyph)
const MAGENTA_HIGH = '#EE17AE'; // --logo-magenta-high (contrast fallback)

