function centerScale(inner, k) {
  if (k === 1) return inner;
  return `<g transform="translate(256 256) scale(${k}) translate(-256 -256)">${inner}</g>`;
}

function glyphInk(glyph, color) {
  const body =
    glyph.type === 'stroke'
      ? `<path d="${glyph.d}" fill="none" stroke="${color}" stroke-width="${glyph.strokeWidth}"/>`
      : `<path d="${glyph.d}" fill="${color}" transform="${glyph.align ?? ''}"/>`;
  return centerScale(body, glyph.zoom ?? 1);
}

function svgDoc(body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">${body}</svg>\n`;
}

// ---------------------------------------------------------------------------
// Variant matrix (v3.1, magenta primary glyph):
//   <t>-seal.svg           yellow ground circle + magenta glyph (primary form)
//   <t>-seal-high.svg      yellow ground circle + magenta highlight-tier glyph (contrast fallback 3.2:1 vs bright 2.9:1)
//   <t>-seal-ink.svg       yellow ground circle + site black glyph (v3 original, contrast 15.3:1)
//   <t>-seal-inverse.svg   black ground circle + yellow glyph (spare for embedding on dark site backgrounds)
//   <t>-ink.svg            magenta glyph on transparent ground (UI already provides a circular container)
//   <t>-ink-currentcolor.svg same as above, currentColor
// ---------------------------------------------------------------------------

function buildVariants(glyph) {
  return {
    'seal.svg': svgDoc(
      `<circle cx="256" cy="256" r="250" fill="${YELLOW}"/>\n${glyphInk(glyph, MAGENTA)}`,
    ),
    'seal-high.svg': svgDoc(
      `<circle cx="256" cy="256" r="250" fill="${YELLOW}"/>\n${glyphInk(glyph, MAGENTA_HIGH)}`,
    ),
    'seal-ink.svg': svgDoc(
      `<circle cx="256" cy="256" r="250" fill="${YELLOW}"/>\n${glyphInk(glyph, INK)}`,
    ),
    'seal-inverse.svg': svgDoc(
      `<circle cx="256" cy="256" r="250" fill="${INK}"/>\n${glyphInk(glyph, YELLOW)}`,
    ),
    'ink.svg': svgDoc(glyphInk(glyph, MAGENTA)),
    'ink-currentcolor.svg': svgDoc(glyphInk(glyph, 'currentColor')),
  };
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

mkdirSync(join(OUT, 'svg'), { recursive: true });

// All variants inlined into preview (self-contained: opens in in-app embedded preview / any browser /
// serverless contexts; relative-path svg/ references 404 and break images in sandboxed previews)
const DOC = {};
for (const [key, glyph] of Object.entries(GLYPHS)) {
  for (const [suffix, doc] of Object.entries(buildVariants(glyph))) {
    // suffix includes .svg (e.g. seal.svg): the filename keeps the extension on disk; DOC keys drop it for icon() lookup
    writeFileSync(join(OUT, 'svg', `${key}-${suffix}`), doc);
    DOC[`${key}-${suffix.replace(/\.svg$/, '')}`] = doc.trimEnd();
  }
}

// Preview page: research conclusions -> new design -> px ladder -> light ground
const icon = (file, size) => `<span class="icon" style="inline-size:${size}px">${DOC[file]}</span>`;
const cell = (file, size) => `<div class="cell">${icon(file, size)}<span>${size}px</span></div>`;
const row = (file) =>
  `<div class="ladder"><b>${file}</b><div class="run">${[128, 64, 32, 20, 16].map((s) => cell(file, s)).join('')}</div></div>`;
const fig = (file, size) => `<figure class="fig">${icon(file, size)}<span>${file}</span></figure>`;

